	Th8_StringAppend(p->interp, &zFull, &nFull, "::", 2);
	Th8_StringAppend(p->interp, &zFull, &nFull, zName, nName);
	Th8_ListAppend(p->interp, p->pzList, p->pnList, zFull, nFull);
