/*
 *---------------------------------------------------------------------------
 *
 * Eagle_AllocateMemory --
 *
 *	This function allocates a block of memory of at least the specified
 *	size.
 *
 * Results:
 *	The pointer to the new memory block -OR- NULL if the memory could not
 *	be obtained.
 *
 * Side effects:
 *	None.
 *
 *---------------------------------------------------------------------------
 */

se_LPVOID
Eagle_AllocateMemory(
    se_SIZE_T size)	/* The size, in bytes, of the memory block to be
			 * allocated. */
{
    se_LPVOID pMemory = NULL;
    se_SIZE_T memorySize;

#if !defined(NO_SIZEOF_ASSERTS)
    assert(sizeof(se_BYTE) >= 1);
#endif

    assert(size >= 0);

    if (size > 0) {
	assert(size <= LIBRARY_MAXIMUM_SIZE_T);
	pMemory = EagleAllocateMemory(size);
    }

    memorySize = EagleMemorySize(pMemory);

    if (pMemory != NULL) {
	memoryBytesAllocated += memorySize;

	LIBRARY_DEBUG(("Eagle_AllocateMemory: 0x%p, requested %d bytes, "
	    "received %d bytes, total now %d bytes\n", pMemory, (int)size,
	    (int)memorySize, (int)memoryBytesAllocated));
    } else {
	LIBRARY_TRACE(("Eagle_AllocateMemory: out of memory (%d)\n",
	    (int)size));
    }

    return pMemory;
}

/*
 *---------------------------------------------------------------------------
 *
 * Eagle_FreeMemory --
 *
 *	This function frees a block of memory that was previously allocated
 *	by the Eagle_AllocateMemory function.
 *
 * Results:
 *	None.
 *
 * Side effects:
 *	None.
 *
 *---------------------------------------------------------------------------
 */

VOID
Eagle_FreeMemory(
    se_LPVOID pMemory)	/* The memory block to se_free.  This memory block must
			 * have been obtained from Eagle_AllocateMemory. */
{
    se_SIZE_T size;

    if (pMemory == NULL)
	return;

    size = EagleMemorySize(pMemory);

#if !defined(NDEBUG)
    se_memset(pMemory, LIBRARY_FREED_MEMORY, size);
#endif

    memoryBytesAllocated -= size;

    LIBRARY_DEBUG(("Eagle_FreeMemory: 0x%p, received %d bytes, total now "
	"%d bytes\n", pMemory, (int)size, (int)memoryBytesAllocated));

    EagleFreeMemory(pMemory);
}

/*
 *---------------------------------------------------------------------------
 *
 * Eagle_FreeElements --
 *
 *	This function frees all memory that is being used to contain the
 *	array of list elements that was allocated by the Eagle_SplitList
 *	function.
 *
 * Results:
 *	None.
 *
 * Side effects:
 *	None.
 *
 *---------------------------------------------------------------------------
 */

VOID
Eagle_FreeElements(
    se_SIZE_T elementCount,	/* The number of list elements. */
    se_LPWSTR *ppElements)		/* The list element array to se_free. */
{
    /*
     * NOTE: The space to hold the element pointers as well as the element
     *       strings themselves is actually one big block; therefore, just
     *       call the normal memory freeing function on it.
     */

    Eagle_FreeMemory(ppElements);
}

/*
 *---------------------------------------------------------------------------
 *
 * Eagle_SplitList --
 *
 *	Splits a list up into its constituent elements.
 *
 * Results
 *	The return value is normally EAGLE_OK, which means that the list was
 *	successfully split up.  If EAGLE_ERROR is returned, it means that
 *	"list" did not have proper list structure; in that case, the error
 *	message will contain a more details.
 *
 * Side effects:
 *	Memory is allocated and possibly freed.
 *
 *---------------------------------------------------------------------------
 */

se_RETURNCODE
Eagle_SplitList(
    se_SIZE_T length,		/* Length of string with list structure. */
    se_LPCWSTR pText,		/* Pointer to string with list structure. */
    se_LPSIZE_T pElementCount,	/* The number of list elements found. */
    se_LPSIZE_T *ppElementLengths,	/* The string lengths of the list elements. */
    se_LPCWSTR **pppElements,	/* The array of list elements. */
    se_LPCWSTR *ppError)		/* The error message, if any. */
{
    se_LPCWSTR l, q, element;
    se_LPSIZE_T argc;
    se_LPWSTR *argv;
    se_LPWSTR p;
    se_SIZE_T allocSize;
    se_SIZE_T listLength, size, i, j, elSize;
    se_BOOL brace;
    se_RETURNCODE result;

    assert(length >= 0);
    assert(pText != NULL);
    assert(pElementCount != NULL);
    assert(ppElementLengths != NULL);
    assert(pppElements != NULL);
    assert(ppError != NULL);

    /*
     * Figure out how much space to allocate.  There must be enough
     * space for both the array of pointers and also for a copy of
     * the list.  To estimate the number of pointers needed, count
     * the number of space characters in the list.
     */

    for (size = 2, j = 0, l = pText; j < length; j++, l++) {
	if (se_iswspace(*l)) { /* INTL: ISO space. */
	    size++;
	    /* Consecutive space can only count as a single list delimiter */
	    while (1) {
		se_WCHAR next;
		if ((j + 1) >= length) {
		    break;
		}
		next = *(l + 1);
		j++; l++;
		if (se_iswspace(next)) {
		    continue;
		}
		break;
	    }
	}
    }
    listLength = length;

    /*
     * Integer overflow check: Verify calculated size does not wrap.
     */

    if (size > (LIBRARY_MAXIMUM_SIZE_T / sizeof(se_SIZE_T))) {
	if (ppError != NULL) {
	    *ppError = EaglePrintf(0,
		UNICODIFY("list too large for element lengths (%d)"),
		(int)size);
	}
	return EAGLE_ERROR;
    }
    allocSize = size * sizeof(se_SIZE_T);
    assert(allocSize > 0);
    assert(allocSize <= LIBRARY_MAXIMUM_SIZE_T);
    argc = Eagle_AllocateMemory(allocSize);
    if (argc == NULL) {
	if (ppError != NULL) {
	    *ppError = EaglePrintf(0,
		UNICODIFY("out of memory for list element lengths (%d)"),
		(int)allocSize);
	}
	return EAGLE_ERROR;
    }

    /*
     * Integer overflow check: Verify calculated size does not wrap.
     */

    if (size > (LIBRARY_MAXIMUM_SIZE_T / sizeof(se_LPWSTR)) || (listLength + 1) >
	    (LIBRARY_MAXIMUM_SIZE_T - size * sizeof(se_LPWSTR)) / sizeof(se_WCHAR)) {
	if (ppError != NULL) {
	    *ppError = EaglePrintf(0,
		UNICODIFY("list too large for element data (%d)"),
		(int)size);
	}
	Eagle_FreeMemory(argc);
	return EAGLE_ERROR;
    }
    allocSize = (size * sizeof(se_LPWSTR)) + ((listLength + 1) * sizeof(se_WCHAR));
    assert(allocSize > 0);
    assert(allocSize <= LIBRARY_MAXIMUM_SIZE_T);
    argv = Eagle_AllocateMemory(allocSize);
    if (argv == NULL) {
	if (ppError != NULL) {
	    *ppError = EaglePrintf(0,
		UNICODIFY("out of memory for list element pointers (%d)"),
		(int)allocSize);
	}
	Eagle_FreeMemory(argc);
	return EAGLE_ERROR;
    }
    q = pText + length;
    for (i = 0, p = (se_LPWSTR)(((se_LPBYTE)argv) + (size * sizeof(se_LPWSTR)));
	    listLength > 0; i++) {
	se_LPCWSTR prevList = pText;

	result = EagleFindElement(pText, listLength, &element, &pText,
				  &elSize, &brace, ppError);
	if (result != EAGLE_OK) {
	    Eagle_FreeMemory(argc);
	    Eagle_FreeMemory(argv);
	    return result;
	}
	listLength -= (se_SIZE_T)(pText - prevList);
	if (element == q) {
	    break;
	}
	if (i >= size) {
	    if (ppError != NULL) {
		*ppError = EaglePrintf(0,
		    UNICODIFY("wrong estimated list size"));
	    }
	    Eagle_FreeMemory(argc);
	    Eagle_FreeMemory(argv);
	    return EAGLE_ERROR;
	}
	if (brace) {
	    se_wmemcpy(p, element, elSize);
	} else {
	    elSize = EagleCopyAndCollapse(elSize, element, p);
	}
	p[elSize] = UNICODIFY('\0');
	argc[i] = elSize;
	argv[i] = p;
	p += elSize + 1;
    }

    argc[i] = 0;
    argv[i] = NULL;

    *pElementCount = i;
    *ppElementLengths = argc;
    *pppElements = (se_LPCWSTR *)argv; /* incompatible-pointer-types warning? */

    return EAGLE_OK;
}

/*
 *---------------------------------------------------------------------------
 *
 * Eagle_JoinList --
 *
 *	Given a collection of strings, merge them together into a single
 *	string that has proper Tcl list structure (i.e. Eagle_SplitList
 *	may be used to retrieve strings equal to the original elements).
 *
 * Results:
 *	A standard Eagle return code.
 *
 * Side effects:
 *	Memory is allocated and possibly freed.
 *
 *---------------------------------------------------------------------------
 */

se_RETURNCODE
Eagle_JoinList(
    se_SIZE_T elementCount,	/* The number of list elements present. */
    se_LPCSIZE_T pElementLengths,	/* The string lengths of the list elements. */
    se_LPCWSTR *ppElements,	/* The list elements. */
    se_LPSIZE_T pLength,		/* The string length of the resulting list. */
    se_LPCWSTR *ppText,		/* The textual representation of the list. */
    se_LPCWSTR *ppError)		/* The error message, if any. */
{
    se_FLAGS localFlags[LIBRARY_LOCAL_FLAGS], *flagPtr;
    se_SIZE_T allocSize;
    se_SIZE_T i, numChars;
    se_LPWSTR result, dst;

    assert(elementCount >= 0);

#if !defined(USE_SYSSTRINGLEN) || !USE_SYSSTRINGLEN
    assert(pElementLengths != NULL);
#else
    assert(pElementLengths == NULL);
#endif

    assert(ppElements != NULL);
    assert(ppText != NULL);
    assert(ppError != NULL);

    /*
     * Pass 1: estimate space, gather flags.
     */

    if (elementCount <= LIBRARY_LOCAL_FLAGS) {
	flagPtr = localFlags;
    } else {
	assert(elementCount > 0);
	if (elementCount > LIBRARY_MAXIMUM_SIZE_T / sizeof(se_FLAGS)) {
	    if (ppError != NULL) {
		*ppError = EaglePrintf(0,
		    UNICODIFY("list too large for element flags (%d)"),
		    (int)elementCount);
	    }
	    return EAGLE_ERROR;
	}
	allocSize = elementCount * sizeof(se_FLAGS);
	assert(allocSize > 0);
	assert(allocSize <= LIBRARY_MAXIMUM_SIZE_T);
	flagPtr = Eagle_AllocateMemory(allocSize);
	if (flagPtr == NULL) {
	    if (ppError != NULL) {
		*ppError = EaglePrintf(0,
		    UNICODIFY("out of memory for list element flags (%d)"),
		    (int)allocSize);
	    }
	    return EAGLE_ERROR;
	}
    }

    numChars = 0;
    for (i = 0; i < elementCount; i++) {
	/*
	 * If necessary, add space for the list element separator.
	 */

	if (i > 0) {
	    numChars++; /* +1 SPACE */
	}

	numChars += EagleScanCountedElement(ppElements[i],
	    SysStringLenWrapper(i) /* NON-PORTABLE? */,
	    &flagPtr[i]);
    }

    /*
     * Pass 2: copy into the result area.
     */

    allocSize = (numChars + 1) * sizeof(se_WCHAR);
    assert(allocSize > 0);
    assert(allocSize <= LIBRARY_MAXIMUM_SIZE_T);
    result = Eagle_AllocateMemory(allocSize);
    if (result == NULL) {
	if (ppError != NULL) {
	    *ppError = EaglePrintf(0,
		UNICODIFY("out of memory for list element text (%d)"),
		(int)allocSize);
	}
	if (flagPtr != localFlags) {
	    Eagle_FreeMemory(flagPtr);
	}
	return EAGLE_ERROR;
    }

    numChars = 0;
    dst = result;
    for (i = 0; i < elementCount; i++) {
	se_SIZE_T eleChars = 0;

	/*
	 * If necessary, add the list element separator.
	 */

	if (i > 0) {
	    *dst = UNICODIFY(' ');
	    eleChars++;
	    dst++;
	}

	eleChars += EagleConvertCountedElement(ppElements[i],
		SysStringLenWrapper(i) /* NON-PORTABLE? */, dst,
		flagPtr[i] | ((i == 0) ? 0 : EAGLE_DONT_QUOTE_HASH));

	numChars += eleChars;
	dst += (eleChars - (i > 0));
    }

    if (flagPtr != localFlags) {
	Eagle_FreeMemory(flagPtr);
    }

    *pLength = numChars;
    *ppText = result;

    return EAGLE_OK;
}


