#  define TH8_OP_UNARY_MINUS 2
#  define TH8_OP_UNARY_PLUS  3
#  define TH8_OP_BITWISE_NOT 4
#  define TH8_OP_LOGICAL_NOT 5
#  define TH8_OP_MULTIPLY    6
#  define TH8_OP_DIVIDE      7
#  define TH8_OP_MODULUS     8
