	if (n < 20 + nMod + 5 * nHalf + nMod) {
	    Th8_SetResultStatic(
	        interp, "SNK: private key blob truncated", TH8_NOLEN);
	    return TH8_ERROR;
	}
	pKey->bHasPrivate = 1;
