	th8WriteLE32(&p[0], DOTNET_SIG_ALG_RSA);    /* SigAlgID */
	th8WriteLE32(&p[4], DOTNET_HASH_ALG_SHA1);   /* HashAlgID */
	th8WriteLE32(&p[8], (unsigned int)nCapi);     /* cbPublicKey */

