/*
 *----------------------------------------------------------------------
 *
 * th8CurlWriteData --
 *
 *	libcurl write callback.  Accumulates received data into
 *	a dynamically growing buffer.
 *
 * Why / How:
 *	Registered with CURLOPT_WRITEFUNCTION.  Each time curl
 *	receives data, this callback appends it to a CurlWriteCtx
 *	buffer, doubling the allocation when needed (minimum 4096).
 *	Uses Th8_AttemptRealloc / Th8_Memcpy so all memory goes
 *	through the interpreter's platform allocator.  Returns 0
 *	on allocation failure to signal curl to abort.
 *
 * Results:
 *	Number of bytes consumed (nBytes), or 0 on OOM.
 *
 * Side effects:
 *	Grows the CurlWriteCtx buffer.
 *
 *----------------------------------------------------------------------
 */

typedef struct {
    char *zBuf;   /* Accumulated data. */
    size_t nBuf;  /* Current length. */
    size_t nAlloc;  /* Allocated capacity. */
    Th8_Interp *interp; /* For Th8_Malloc/Realloc. */
} CurlWriteCtx;

static size_t
th8CurlWriteData(
    void *ptr,   /* Data from curl. */
    size_t size,  /* Element size (always 1). */
    size_t nmemb,  /* Number of elements. */
    void *userdata)  /* CurlWriteCtx pointer. */
{
    CurlWriteCtx *ctx = (CurlWriteCtx *)userdata;
    size_t nBytes = 0;
    size_t nNeeded = 0;

    if (TH8_SAFE_MUL_SIZE(size, nmemb, &nBytes)) return 0;
    {
	size_t nTmp = 0;
	if (TH8_SAFE_ADD_SIZE(ctx->nBuf, nBytes, &nTmp)) return 0;
	if (TH8_SAFE_ADD_SIZE(nTmp, 1, &nNeeded)) return 0;
    }

    if (nNeeded > ctx->nAlloc) {
	size_t nNew = ctx->nAlloc * 2;
	char *zNew;

	if (nNew < nNeeded) nNew = nNeeded;
	if (nNew < 4096) nNew = 4096;
	zNew = (char *)Th8_AttemptRealloc(ctx->interp, ctx->zBuf, nNew);
	if (!zNew) return 0;  /* Signal error to curl */
	ctx->zBuf = zNew;
	ctx->nAlloc = nNew;
    }
    Th8_Memcpy(ctx->interp, &ctx->zBuf[ctx->nBuf], ptr, nBytes);
    ctx->nBuf += nBytes;
    ctx->zBuf[ctx->nBuf] = '\0';
    return nBytes;
}


