static const size_t th8_keyTest_size = sizeof(th8_keyTest_data);

/*
 *----------------------------------------------------------------------
 *
 * Th8_GetEmbeddedKeyTest --
 *
 *	Return a pointer to the embedded test key blob and its
 *	size in bytes.  Only available when TH8_ENABLE_TEST_KEY
 *	is defined.
 *
 * Why / How:
 *	The test key enables the test suite to verify signature
 *	operations without requiring the production root key.
 *	Compiled as a static byte array generated by mkkey.tcl.
 *
 * Results:
 *	Pointer to the key blob (static storage).  *pnData is
 *	set to the blob size if pnData is non-NULL.
 *
 * Side effects:
 *	None.
 *
 *----------------------------------------------------------------------
 */

const unsigned char *
Th8_GetEmbeddedKeyTest(size_t *pnData)
{
    if (pnData) *pnData = th8_keyTest_size;
    return th8_keyTest_data;
}

#endif /* TH8_ENABLE_CRYPTOGRAPHY && TH8_ENABLE_TEST_KEY */

